"""Supporting pages for the compact marketing calendar; generated by the main builder."""
import re

def build(root,sections,decisions,history,data,escape):
    e=escape
    panels={key:re.search(r'<details class="panel" id="'+key+r'"[^>]*>.*?</details>',sections,re.S).group() for key in ['traffic','production','scorecard','files']}
    # Open the actual page content; the calendar stays focused on posts.
    panels={k:v.replace(f'id="{k}"',f'id="{k}" open',1) for k,v in panels.items()}
    titles=[('MARKETING_PRODUCTION.html','Videos & production'),('MARKETING_STRATEGY.html','Strategy & measurement'),('MARKETING_REFERENCE.html','Sources & history')]
    navigation='<nav class="support-nav" aria-label="Marketing pages"><a href="MARKETING_PLAN.html#top">← Marketing plan</a>'+''.join(f'<a href="{file}">{title}</a>' for file,title in titles)+'</nav>'
    archive=f'''<details class="panel" id="archive" open><summary>98 source decisions</summary><p>Original ideas and their merge decisions. These are reference records, not another posting queue.</p><div class="table-wrap"><table><thead><tr><th>Source / old date</th><th>Original idea</th><th>Decision and retained item</th></tr></thead><tbody>{''.join(decisions)}</tbody></table></div></details>'''
    recorded=data['recorded_schedule']
    existing=f'''<details class="panel" id="existing" open><summary>Preserved publication records</summary><p><b>28 October 19:30 Sydney:</b> {e(recorded['title'])} · {e(recorded['status'])}. <a href="{e(recorded['asset'])}">Original artwork</a>. Do not repost from the old 29 October date. <span id="recorded-browser-status"></span></p><p>Earlier launch-week records below are preserved source notes, not current Meta verification.</p><div class="table-wrap"><table><thead><tr><th>Original slot</th><th>Post</th><th>Recorded status</th></tr></thead><tbody>{history}</tbody></table></div></details>'''
    bodies={
        'MARKETING_PRODUCTION.html':panels['production'],
        'MARKETING_STRATEGY.html':panels['traffic']+panels['scorecard'],
        'MARKETING_REFERENCE.html':existing+panels['files']+archive,
    }
    review_script='''(()=>{let saved={};for(const key of ['dsb-home-review-20261102','dsb-marketing-review-20261023']){try{Object.assign(saved,JSON.parse(localStorage.getItem(key)||'{}'));}catch{}}for(const row of document.querySelectorAll('[data-archive-id]')){const s=saved[row.dataset.archiveId];if(s)row.querySelector('.archive-review').textContent='Browser review: '+(s.status||'review available')+(s.comment?' · '+s.comment:'');}const el=document.getElementById('recorded-browser-status');if(el&&saved['r-01'])el.textContent='Preserved browser record: '+(saved['r-01'].status||'review available')+'.';if(location.hash){const el=document.getElementById(location.hash.slice(1));if(el){let d=el.closest('details');while(d){d.open=true;d=d.parentElement.closest('details');}requestAnimationFrame(()=>el.scrollIntoView());}}})();'''
    for filename,title in titles:
        body=bodies[filename]
        # Cross-page links open the original calendar item and its media.
        body=re.sub(r'href="#(?!top\b)([^"]+)"',r'href="MARKETING_PLAN.html#\1"',body)
        page=f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DigiStayBook · {e(title)}</title><link rel="stylesheet" href="campaigns/merged-2026-10-28/plan.css"></head><body class="support-page"><header id="top"><div class="eyebrow">DIGISTAYBOOK / MARKETING</div><h1>{e(title)}</h1>{navigation}</header><main class="info-page">{body}<nav class="post-nav"><a href="MARKETING_PLAN.html#posts">← Post overview</a><a href="#top">↑ Top</a></nav></main><nav class="mobile-jump" aria-label="Quick navigation"><a href="MARKETING_PLAN.html#posts">← Post overview</a><a href="MARKETING_PLAN.html#top">↑ Plan top</a></nav><script>{review_script}</script></body></html>'''
        (root/filename).write_text(page,encoding='utf-8')
    return titles
